"""
Candidate 5: Parameterized Function Family Optimization

Instead of optimizing individual elements, parameterize f with a small number
of parameters and optimize those. This reduces the search space dramatically
and allows global optimization over parameters.

Families explored:
- Power law: f(x) = x^alpha for x in [0,1]
- Double power law: f(x) = x^alpha for x < t, f(x) = (1-x)^beta for x >= t  
- Two-level with smooth transition
- Polynomial with constraints
- Custom: f(x) = A * x^a + B * (1-x)^b
"""
import numpy as np
import sys, time
sys.path.insert(0, '/home/crv1pi/agent_runs/ac2_evo_s1')
from eval import evaluate_sequence

def compute_score(f):
    f = np.asarray(f, dtype=np.float64)
    f = np.maximum(0, f)
    c = np.convolve(f, f)
    N = len(c)
    dx = 1.0 / (N + 1)
    y = np.concatenate(([0], c, [0]))
    l2_sq = dx / 3.0 * np.sum(y[:-1]**2 + y[:-1]*y[1:] + y[1:]**2)
    l1 = np.sum(np.abs(c)) / (N + 1)
    linf = np.max(np.abs(c))
    return l2_sq / (l1 * linf)

def construct_function(seed=42, budget_s=1000, **kwargs):
    start = time.time()
    np.random.seed(seed)

    best_score = 0
    best_seq = None
    N = 5000

    x = np.linspace(0, 1, N)

    def try_func(params, func_name):
        nonlocal best_score, best_seq
        if len(params) == 1:
            alpha, = params
            f = x**alpha
        elif len(params) == 2:
            alpha, beta = params
            f = x**alpha + x**beta
        elif len(params) == 3:
            A, alpha, beta = params
            f = A * x**alpha + (1-A) * (1-x)**beta
        elif len(params) == 4:
            A, a, B, b = params
            f = A * x**a + B * (1-x)**b
        elif len(params) == 5:
            A, a, t, C, d = params
            f = np.where(x < t, A * x**a, C * (x-t)**d)
        elif len(params) == 6:
            A, a, B, b, C, c2 = params
            f = A * x**a + B * (1-x)**b + C * np.sin(np.pi * c2 * x)
        else:
            return

        f = np.maximum(0, f)
        if np.sum(f) < 0.01:
            return
        try:
            s = compute_score(f)
            if s > best_score:
                best_score = s
                best_seq = f.copy()
                print(f"  {func_name}: {s:.6f} (params={params})")
        except:
            pass

    # === Power law family ===
    print("=== Power law f(x) = x^alpha ===")
    for alpha in np.linspace(-0.5, 5, 200):
        try_func((alpha,), "x^alpha")

    # === Two power laws ===
    print("\n=== Sum of power laws ===")
    for a in np.linspace(-0.5, 5, 50):
        for b in np.linspace(-0.5, 5, 50):
            if abs(a-b) < 0.1:
                continue
            try_func((a, b), "x^a + x^b")

    # === Weighted sum of power laws ===
    print("\n=== A*x^a + (1-A)*(1-x)^b ===")
    for A in np.linspace(0.01, 0.99, 20):
        for a in np.linspace(0.1, 5, 20):
            for b in np.linspace(0.1, 5, 20):
                try_func((A, a, b), "weighted power")

    # === Four-parameter family ===
    print("\n=== A*x^a + B*(1-x)^b ===")
    for A in np.logspace(-2, 2, 20):
        for a in np.linspace(0.1, 3, 10):
            for B in np.logspace(-2, 2, 20):
                for b in np.linspace(0.1, 3, 10):
                    try_func((A, a, B, b), "A*x^a + B*(1-x)^b")

    # === Two-piece power law ===
    print("\n=== Two-piece: A*x^a for x<t, C*(x-t)^d for x>=t ===")
    for A in [0.5, 1, 2, 5, 10]:
        for a in [0.1, 0.5, 1, 2, 3]:
            for t in np.linspace(0.1, 0.9, 20):
                for C in [0.1, 0.5, 1, 2, 5, 10]:
                    for d in [0.1, 0.5, 1, 2, 3]:
                        try_func((A, a, t, C, d), "two-piece")

    print(f"\nParameter search best: {best_score:.6f}")

    # === Fine-grained optimization on best ===
    if best_seq is not None and time.time() - start < budget_s - 30:
        print("\n=== Fine optimization ===")
        f = best_seq.copy()
        n = len(f)

        # Coordinate ascent
        for epoch in range(50):
            improved = False
            for i in range(n):
                if time.time() - start > budget_s - 5:
                    return best_seq.tolist()
                old = f[i]
                for factor in [0.5, 0.7, 0.9, 1.1, 1.3, 1.5, 2.0]:
                    f[i] = max(0, old * factor)
                    s = compute_score(f)
                    if s > best_score:
                        best_score = s
                        best_seq = f.copy()
                        improved = True
                        break
                    f[i] = old
            if not improved:
                break
            if epoch % 10 == 0:
                print(f"  Epoch {epoch}: {best_score:.6f}")

    print(f"Final: {best_score:.6f}")
    return best_seq.tolist()

if __name__ == '__main__':
    seq = construct_function(budget_s=900)
    score = evaluate_sequence(seq)
    print(f"Verified: {score:.6f}")
    np.save('/home/crv1pi/agent_runs/ac2_evo_s1/run/attempts/cand5_parametric.npy', np.array(seq))

