import numpy as np
from eval import evaluate_sequence

def score(f):
    return evaluate_sequence(np.asarray(f, dtype=np.float64).tolist())

N = 5000

# Deep explore power law family: f[i] = (a + b*i)^alpha
print('=== Power law: (a + b*i)^alpha ===')
best = 0
for a in [0.1, 0.5, 1, 2, 5, 10]:
    for b in [0.1, 0.5, 1, 2, 5, 10]:
        for alpha in np.linspace(-2, 3, 100):
            x = a + b * np.arange(N) / N
            f = x**alpha
            if np.any(np.isinf(f)) or np.any(np.isnan(f)):
                continue
            f = np.clip(f, 0, 1000)
            s = score(f)
            if s > best:
                best = s
                if s > 0.82:
                    print(f'  a={a}, b={b}, alpha={alpha:.3f}: {s:.6f}')

print(f'Best power law: {best:.6f}')

# Explore around best parameters
print()
print('=== Fine search around best ===')
for alpha in np.linspace(-1.2, -0.5, 70):
    for a in np.logspace(-1, 2, 20):
        for b in np.logspace(-1, 2, 20):
            x = a + b * np.arange(N) / N
            f = x**alpha
            if np.any(np.isinf(f)):
                continue
            f = np.clip(f, 0, 1000)
            s = score(f)
            if s > best:
                best = s
                print(f'  a={a:.3f}, b={b:.3f}, alpha={alpha:.3f}: {s:.6f}')

print(f'Fine best: {best:.6f}')

# Reverse direction
print()
print('=== Reverse: high values first ===')
for alpha in np.linspace(-1.2, -0.5, 70):
    for a in np.logspace(-1, 2, 20):
        for b in np.logspace(-1, 2, 20):
            x = a + b * (1 - np.arange(N) / N)
            f = x**alpha
            if np.any(np.isinf(f)):
                continue
            f = np.clip(f, 0, 1000)
            s = score(f)
            if s > best:
                best = s
                print(f'  REV a={a:.3f}, b={b:.3f}, alpha={alpha:.3f}: {s:.6f}')

print(f'Reverse best: {best:.6f}')
